using System.Diagnostics;
using System.Globalization;
using System.Text.Json;
namespace LeoLauncher;
static class LeoActions
{
    public static readonly string[] Names=["launcher_open","clipboard_open","clipboard_pin_text","football_open","football_facts","todos_open","todo_list","todo_add","todo_complete","todo_remind","todo_repeat","todo_edit","todo_move","todo_snooze","music_open","music_search","music_play","music_playlists","music_playlist_play","music_step","music_playlist_name","todo_postpone","todo_stop_repeat","match_add","web_search","watch_open","proxy_status","proxy_on","proxy_off","terminal_open","pet_size","fullscreen_hide","favorite_app","alias_app","files_open"];
    public static readonly HashSet<string> ReadOnly=["football_facts","todo_list","proxy_status","music_search","music_playlists"];
    public const string Description="按action填写value：界面打开/代理/终端/files_open用空字符串；web_search为关键词；watch_open为1到4；pet_size为80到230整数；fullscreen_hide为on/off；clipboard_pin_text为用户明确要求保存的文字。football_facts为球队名或今晚比赛。todo_list为YYYY-MM-DD或week:YYYY-MM-DD；todo_add为JSON字符串{title,day(YYYY-MM-DD),reminder(可省略，带时区的ISO时间)}；todo_complete为从todo_list获得的精确id；todo_remind为JSON{id,time(带时区ISO时间或空字符串取消)}；favorite_app为JSON{app_id,enabled(bool)}，alias_app为JSON{app_id,alias}，app_id必须来自search_apps。todos_open的value可为week。不要猜测待办id或应用id。todo_repeat为JSON{title,day,frequency(daily或weekly),reminder(可省略)}；todo_postpone为精确事项id，或day:YYYY-MM-DD批量顺延该日未完成；todo_stop_repeat为JSON{series_id,after(YYYY-MM-DD)}停止该日期之后的重复；match_add为football_facts返回的ESPN比赛Id，自动加入清单并提前10分钟提醒，勿猜id。todo_edit为JSON{id,title}只修改本次标题；todo_move为JSON{id,day(YYYY-MM-DD)}改期并移动提醒；todo_snooze为JSON{id,minutes(10或60)}稍后提醒。music_open为空字符串或搜索词；music_search为歌名/歌手，返回候选Id；music_play为music_search提供的精确Id，只有用户要求播放时使用。不要猜歌曲编号，存在歧义先给出候选供选择。music_step为1或-1，手动切换当前Leo点歌列表的下一首或上一首；music_playlist_name为用户明确说出的本地歌单名称，精确匹配后点首曲，不弹音乐窗口。music_playlists为空字符串，返回本地常听歌单Id和名称；music_playlist_play为查询所得精确歌单Id，直接向客户端发送歌单第一首，不弹出音乐窗口，也不承诺自动连播。音乐工具只能报告歌曲已发送客户端，不能假称实际已播放。提醒只在Leo运行时触发。只在用户明确要求时改变代理、收藏、剪贴板或其它设置。";
}
sealed partial class PetForm
{
    readonly System.Windows.Forms.Timer reminderTimer=new(){Interval=15000};
    readonly TodoStore todoStore;
    void CheckReminders(){if(hiddenForFullscreen||QuietHours.Load().Contains(DateTime.Now)){if(reminders?.Visible==true)reminders.Hide();return;}if(reminders!=null&&!reminders.IsDisposed&&!reminders.Visible&&reminders.PendingCount>0)reminders.Present([]);try{todoStore.EnsureThrough(DateOnly.FromDateTime(DateTime.Today).AddDays(35));var due=todoStore.Due(DateTimeOffset.Now).Where(t=>!matchSyncBusy||t.MatchId==null).ToArray();if(due.Length==0)return;if(reminders==null||reminders.IsDisposed)reminders=new ReminderForm(todoStore,OpenReminderTask);reminders.Present(due);todoStore.MarkNotified(due.Select(t=>t.Id),DateTimeOffset.Now);tray.BalloonTipTitle="Leo · 清单提醒";tray.BalloonTipText=string.Join("\n",due.Take(3).Select(t=>t.Title))+"\n点提醒窗口可延后10分钟或1小时";tray.ShowBalloonTip(10000);}catch{/* A failed save remains eligible for the next check. */}}
    async Task<string> ExecuteLeoAction(string action,string value,CancellationToken token){token.ThrowIfCancellationRequested();if(!LeoActions.Names.Contains(action))throw new ArgumentException("不支持的功能");
        switch(action){
            case "launcher_open":ShowLauncher();return "已打开应用搜索，可以查看收藏、设置简称与排序。";
            case "clipboard_open":launcher.OpenClipboardFromAssistant();return "已打开剪贴板历史与收藏。";
            case "clipboard_pin_text":return launcher.PinClipboardText(value);
            case "football_open":launcher.OpenFootballFromAssistant();return "已打开足球日程、球队详情与观赛网址。";
            case "todos_open":ShowTodos();todoWindow!.View.SetWeek(value=="week");return "已打开清单。";
            case "todo_list":{bool week=value.StartsWith("week:");string date=week?value[5..]:value;var day=string.IsNullOrWhiteSpace(date)?DateOnly.FromDateTime(DateTime.Today):DateOnly.ParseExact(date,"yyyy-MM-dd",CultureInfo.InvariantCulture);todoStore.EnsureThrough(day.AddDays(7));return JsonSerializer.Serialize(week?todoStore.ForWeek(day):todoStore.ForDay(day));}
            case "todo_add":{using var doc=JsonDocument.Parse(value);var r=doc.RootElement;var day=DateOnly.ParseExact(r.GetProperty("day").GetString()!,"yyyy-MM-dd",CultureInfo.InvariantCulture);DateTimeOffset? time=null;if(r.TryGetProperty("reminder",out var at)&&!string.IsNullOrWhiteSpace(at.GetString()))time=FutureTime(at.GetString()!);var task=todoStore.Add(r.GetProperty("title").GetString()!,day,time);todoWindow?.View.Render();return JsonSerializer.Serialize(new{success=true,task=todoStore.Items.Single(t=>t.Id==task.Id)});}
            case "todo_edit":{using var doc=JsonDocument.Parse(value);todoStore.Rename(doc.RootElement.GetProperty("id").GetString()!,doc.RootElement.GetProperty("title").GetString()!);return "已修改事项标题。";}
            case "todo_move":{using var doc=JsonDocument.Parse(value);todoStore.MoveTo(doc.RootElement.GetProperty("id").GetString()!,DateOnly.ParseExact(doc.RootElement.GetProperty("day").GetString()!,"yyyy-MM-dd",CultureInfo.InvariantCulture));return "已修改日期，提醒时间同步移动。";}
            case "todo_snooze":{using var doc=JsonDocument.Parse(value);int minutes=doc.RootElement.GetProperty("minutes").GetInt32();todoStore.Snooze(doc.RootElement.GetProperty("id").GetString()!,minutes,DateTimeOffset.Now);return "已安排"+minutes+"分钟后再次提醒。";}
            case "music_step":return launcher.MusicWithoutOpening().Step(value=="1"?1:value=="-1"?-1:throw new ArgumentException("请选择上一首或下一首"));
            case "music_playlist_name":return launcher.MusicWithoutOpening().PlayByName(value);
            case "music_playlists":return JsonSerializer.Serialize(launcher.MusicWithoutOpening().Library.Items.Select(p=>new{p.Id,p.Name,p.Pinned,Count=p.Songs.Count}));
            case "music_playlist_play":if(!launcher.MusicWithoutOpening().PlayPlaylist(value))throw new ArgumentException("歌单为空或无法发送播放请求，请检查歌曲与QQ音乐客户端。");return "已将常听歌单第一首发送QQ音乐客户端。";
            case "music_open":{var panel=launcher.OpenMusicFromAssistant();if(value.Length>0)await panel.SearchAsync(value);return "已打开QQ音乐点歌面板。";}
            case "music_search":{var panel=launcher.OpenMusicFromAssistant();await panel.SearchAsync(value);return JsonSerializer.Serialize(panel.Candidates);}
            case "music_play":{var panel=launcher.OpenMusicFromAssistant();if(!panel.TryPlayCandidate(value))throw new ArgumentException("无法发送歌曲，请先搜索并使用候选编号，或检查QQ音乐是否已安装。");return "已将歌曲发送到QQ音乐客户端，请在客户端确认播放；登录和歌曲权限由QQ音乐处理。";}
            case "todo_repeat":{using var doc=JsonDocument.Parse(value);var r=doc.RootElement;var start=DateOnly.ParseExact(r.GetProperty("day").GetString()!,"yyyy-MM-dd",CultureInfo.InvariantCulture);DateTimeOffset? remind=null;if(r.TryGetProperty("reminder",out var at)&&!string.IsNullOrWhiteSpace(at.GetString()))remind=FutureTime(at.GetString()!);var task=todoStore.AddRepeating(r.GetProperty("title").GetString()!,start,r.GetProperty("frequency").GetString()!,remind);return JsonSerializer.Serialize(new{success=true,task});}
            case "todo_postpone":{if(value.StartsWith("day:")){var date=DateOnly.ParseExact(value[4..],"yyyy-MM-dd",CultureInfo.InvariantCulture);int count=todoStore.Postpone(todoStore.ForDay(date).Where(t=>t.Completed==null).Select(t=>t.Id));return "已顺延"+count+"项，提醒时间同步移动。";}var task=todoStore.Items.SingleOrDefault(t=>t.Id==value)??throw new ArgumentException("事项不存在，请先查询清单");if(task.Completed!=null)throw new ArgumentException("已完成事项无需顺延");var next=todoStore.PostponeDay(value);todoStore.Postpone([value]);return "已顺延至"+next.ToString("yyyy-MM-dd")+"，提醒时间同步移动。";}
            case "todo_stop_repeat":{using var doc=JsonDocument.Parse(value);todoStore.StopRepeating(doc.RootElement.GetProperty("series_id").GetString()!,DateOnly.ParseExact(doc.RootElement.GetProperty("after").GetString()!,"yyyy-MM-dd",CultureInfo.InvariantCulture));return "已停止后续重复，已完成记录和此前事项保留。";}
            case "match_add":{var options=new List<(FootballMatch Match,DateTimeOffset Updated)>();var cache=FootballFeed.LoadCache();options.AddRange(cache.Matches.Select(m=>(m,cache.Updated)));foreach(var name in FootballForm.FixedFollowing){var data=TeamData.Load(Club.For(name));options.AddRange(data.Matches.Select(m=>(m,data.MatchesUpdated)));}var match=options.Where(x=>x.Match.Id==value).OrderByDescending(x=>x.Updated).Select(x=>x.Match).FirstOrDefault()??throw new ArgumentException("未找到已查询的比赛，请先football_facts获取赛程");var result=todoStore.AddMatch(match,DateTimeOffset.Now);return JsonSerializer.Serialize(new{success=true,result.Added,result.Task});}
            case "todo_complete":{var task=todoStore.Items.SingleOrDefault(t=>t.Id==value)??throw new ArgumentException("事项ID不存在，请先查询清单");if(task.Completed==null)todoStore.Toggle(task.Id);todoWindow?.View.Render();return "已完成："+task.Title;}
            case "todo_remind":{using var doc=JsonDocument.Parse(value);string id=doc.RootElement.GetProperty("id").GetString()!;var task=todoStore.Items.SingleOrDefault(t=>t.Id==id)??throw new ArgumentException("事项ID不存在");string time=doc.RootElement.GetProperty("time").GetString()??"";todoStore.SetReminder(id,time.Length==0?null:FutureTime(time));todoWindow?.View.Render();return time.Length==0?"已取消提醒":"已设置提醒："+task.Title+"，"+FutureTime(time).ToLocalTime().ToString("MM-dd HH:mm")+"。Leo运行时生效。";}
            case "web_search":if(string.IsNullOrWhiteSpace(value))throw new ArgumentException("请输入搜索内容");if(!previewMode)Process.Start(FootTools.EdgeStart(value));return "已用Edge搜索："+value;
            case "watch_open":{if(!int.TryParse(value,out var index)||index<1||index>4)throw new ArgumentException("观赛入口为1到4");var link=new WatchLinkStore(previewMode?null:Path.Combine(Store.Root,"leo-watch-links.json")).Items[index-1];if(link.Url.Length==0)throw new ArgumentException("这个观赛入口还没填写网址，请在足球窗口编辑");if(!previewMode)Process.Start(FootTools.EdgeUrlStart(link.Url));return "已用Edge打开："+link.Name;}
            case "proxy_status":return JsonSerializer.Serialize(previewMode?new ProxyStatus(true,false,"示例代理已关闭"):ClashProxy.ReadStatus());
            case "proxy_on":case "proxy_off":{if(previewMode)return "示例模式，不切换系统代理";bool desired=action=="proxy_on";var before=await Task.Run(ClashProxy.ReadStatus,token);if(!before.Running||before.Enabled==null)throw new InvalidOperationException(before.Description);if(before.Enabled==desired)return desired?"系统代理已经开启":"系统代理已经关闭";token.ThrowIfCancellationRequested();var after=await Task.Run(ClashProxy.Toggle,token);if(after.Enabled!=desired)throw new InvalidOperationException("代理状态已变化，请重新检查");return desired?"已开启系统代理":"已关闭系统代理";}
            case "terminal_open":if(!previewMode)Process.Start(FootTools.TerminalStart());return "已请求打开管理员终端；是否授权由Windows确认。";
            case "pet_size":{if(!int.TryParse(value,out int size)||size<80||size>230)throw new ArgumentException("大小范围80至230");prefs.PetSize=size;ResizePet();if(!previewMode)Store.Save(prefs);return "Leo大小已调整为"+size;}
            case "fullscreen_hide":if(value is not("on" or "off"))throw new ArgumentException("请使用on或off");prefs.HideInFullscreen=value=="on";if(!previewMode)Store.Save(prefs);PollFullscreen();return prefs.HideInFullscreen?"已开启全屏自动隐藏":"已关闭全屏自动隐藏";
            case "favorite_app":case "alias_app":{using var doc=JsonDocument.Parse(value);var r=doc.RootElement;string id=r.GetProperty("app_id").GetString()!;var app=launcher.FileApplications.FirstOrDefault(a=>AppTools.Id(a)==id)??throw new ArgumentException("应用ID不存在，请先search_apps");if(action=="favorite_app"){bool enabled=r.GetProperty("enabled").GetBoolean();prefs.Favorites.RemoveAll(t=>t.Equals(app.Target,StringComparison.OrdinalIgnoreCase));if(enabled)prefs.Favorites.Add(app.Target);}else{string alias=r.GetProperty("alias").GetString()?.Trim()??"";if(alias.Length<1||alias.Length>30)throw new ArgumentException("简称应为1至30个字");prefs.Aliases[app.Target]=(prefs.Aliases.GetValueOrDefault(app.Target)??[]).Append(alias).Distinct().ToArray();}if(!previewMode)Store.Save(prefs);return "已更新"+app.Name+(action=="alias_app"?"的简称":"的收藏状态");}
            case "files_open":if(!previewMode){using var picker=new OpenFileDialog{Title="选择要交给Leo的文件",Multiselect=true};if(picker.ShowDialog()!=DialogResult.OK)return "已取消选择文件";FileDropActions.Open(picker.FileNames,launcher.FileApplications);}return "已打开Leo文件操作，可复制路径、打开所在文件夹或选择应用。";
            case "football_facts":{string team=QuickRouter.Team(value);if(team.Length>0){var club=Club.For(team);var data=TeamData.Load(club);bool stale=false;if(!previewMode&&(data.MatchesUpdated<DateTimeOffset.UtcNow.AddMinutes(-10)||data.TableUpdated<DateTimeOffset.UtcNow.AddMinutes(-10))){var result=await TeamData.Fetch(club,data,token);data=result.Data;stale=result.MatchesFailed||result.TableFailed;}return JsonSerializer.Serialize(new{source="ESPN",now=DateTimeOffset.Now,team,stale,data.MatchesUpdated,data.TableUpdated,matches=data.Matches.OrderByDescending(m=>m.Kickoff).Take(25),table=data.Rows});}var cache=FootballFeed.LoadCache();if(!previewMode&&cache.Updated<DateTimeOffset.UtcNow.AddMinutes(-10))cache=await FootballFeed.FetchAsync(cache,token);return JsonSerializer.Serialize(new{source="ESPN",cache.Updated,cache.FailedSources,matches=cache.Matches.Where(m=>FootballFeed.IsRecent(m,DateTimeOffset.UtcNow)&&(FootballFeed.FollowTags(m,FootballForm.FixedFollowing).Length>0||FootballFeed.IsFocus(m))).OrderBy(m=>m.Kickoff).Take(30)});}
        }throw new ArgumentException("不支持的功能");
    }
    public async Task<Dictionary<string,bool>> VerifyBrainActions(){var checks=new Dictionary<string,bool>();var token=CancellationToken.None;string day=DateTime.Today.AddDays(2).ToString("yyyy-MM-dd");await ExecuteLeoAction("todo_add",JsonSerializer.Serialize(new{title="工具测试事项",day,reminder=DateTimeOffset.Now.AddDays(2).ToString("O")}),token);var task=todoStore.Items.Single();checks["brain_creates_dated_task_and_reminder"]=task.Day==DateOnly.FromDateTime(DateTime.Today.AddDays(2))&&task.Reminder!=null;await ExecuteLeoAction("todos_open","week",token);checks["brain_and_planner_share_same_store"]=todoWindow?.Count==1&&todoWindow.View.IsWeekly;string listed=await ExecuteLeoAction("todo_list",day,token);checks["brain_reads_actual_task_ids"]=listed.Contains(task.Id);await ExecuteLeoAction("todo_complete",task.Id,token);checks["brain_completes_task_in_planner"]=todoStore.Items.Single().Completed!=null&&todoWindow?.CompletedCount==1;await ExecuteLeoAction("todo_remind",JsonSerializer.Serialize(new{id=task.Id,time=""}),token);checks["brain_cancels_existing_reminder"]=todoStore.Items.Single().Reminder==null;try{await ExecuteLeoAction("todo_remind",JsonSerializer.Serialize(new{id="missing",time=""}),token);checks["brain_rejects_unknown_task_id"]=false;}catch(ArgumentException){checks["brain_rejects_unknown_task_id"]=true;}todoWindow?.Close();return checks;}
    static DateTimeOffset FutureTime(string value){if(!System.Text.RegularExpressions.Regex.IsMatch(value,@"(?:Z|[+-]\d{2}:\d{2})$"))throw new ArgumentException("提醒时间应带时区，例如+08:00");var time=DateTimeOffset.Parse(value,CultureInfo.InvariantCulture);if(time<=DateTimeOffset.Now)throw new ArgumentException("提醒时间必须在未来");return time;}
}
